  'international-global-marketing',
  null,
  'International/Global Marketing',
  'International/Global Marketing',
  'This course prepares students to design, justify, and execute marketing strategy across borders. Students learn how culture, institutions, trade policy, market data, digital platforms, customer behavior, channel systems, pricing, brand architecture, regulation, sustainability, and geopolitical risk shape international marketing decisions. The course culminates in a market-entry or global expansion plan supported by data, customer insight, financial logic, and ethical judgment.',
  $igmjson${"slug": "international-global-marketing", "title": "International/Global Marketing", "description": "This course prepares students to design, justify, and execute marketing strategy across borders. Students learn how culture, institutions, trade policy, market data, digital platforms, customer behavior, channel systems, pricing, brand architecture, regulation, sustainability, and geopolitical risk shape international marketing decisions. The course culminates in a market-entry or global expansion plan supported by data, customer insight, financial logic, and ethical judgment.", "topics": [{"id": "4fffd20c-0835-42c7-8f2e-b9eaf8d92050", "type": "topic", "title": "Global Marketing Environment and Strategic Mindset", "description": "Students begin by learning how globalization, regionalization, technology, institutions, and consumer change reshape marketing decisions across borders.", "children": [{"id": "9ee59ef7-b6a5-4fa6-9f84-97c663fbd1a8", "type": "subtopic", "title": "Globalization, regionalization, and deglobalization", "children": [{"id": "45a5439b-6c12-4beb-9b8d-40270d0dd15b", "type": "concept", "title": "Global value chains and market interdependence"}, {"id": "5ca8dd80-cbe3-46ef-b580-2309fea822d3", "type": "concept", "title": "Regional blocs such as EU, USMCA, ASEAN, and AfCFTA"}, {"id": "1ad8f61d-39f4-4230-99de-895e55dfb6f8", "type": "concept", "title": "Resilience, reshoring, friend-shoring, and market fragmentation"}], "description": "The point is to see global marketing as a shifting strategic context, not simply selling the same product abroad."}, {"id": "600fe52f-0bd8-4747-8fd1-25e7ee0bbda7", "type": "subtopic", "title": "Global marketing strategy logic", "children": [{"id": "0ce8df60-e5c2-4490-8753-e9e3b9dd63d6", "type": "concept", "title": "Global integration versus local responsiveness"}, {"id": "1da5741e-a9a6-4b1d-af7d-6dce73072024", "type": "concept", "title": "Scale economies and local relevance"}, {"id": "d6258c03-4b54-4a6c-8ffc-ec9fda10f63c", "type": "concept", "title": "Global, regional, and local roles"}], "description": "Students learn how international marketing connects corporate strategy, competitive advantage, customer insight, and local execution."}, {"id": "a6b9fcd7-5ddc-4bfd-ba33-98db25e3b790", "type": "subtopic", "title": "Country and category opportunity framing", "children": [{"id": "d3bed472-c9e7-4c48-b103-a285a7ccb7ca", "type": "concept", "title": "Market size, growth, and profitability"}, {"id": "9567285b-90c6-4bca-b1a6-4972d78a4f8e", "type": "concept", "title": "Competitive intensity and white space"}, {"id": "0dff2753-5b32-4ebf-b84e-8646059b8c0b", "type": "concept", "title": "Capability fit and strategic priority"}], "description": "The gist is to distinguish country attractiveness from category readiness and company fit."}]}, {"id": "e5fabc1f-b69d-4015-9fee-b581224b1b90", "type": "topic", "title": "Country Screening, Market Attractiveness, and Data Sources", "description": "This topic builds the data discipline needed to choose markets using evidence rather than anecdotes or stereotypes.", "children": [{"id": "bf8f5d76-5632-4961-ac6a-8f2023186419", "type": "subtopic", "title": "Macro and market indicators", "children": [{"id": "5b924152-4ca4-47ea-8b66-46e87ecb65f4", "type": "concept", "title": "World Bank, OECD, IMF, WTO, and trade data"}, {"id": "e70a13ac-eb7f-4c32-a5a9-2eacda3706fb", "type": "concept", "title": "Population, income, urbanization, and category penetration"}, {"id": "9a2ce231-1519-4653-979f-5d28f8e0902b", "type": "concept", "title": "Data quality, comparability, and missingness"}], "description": "Students use public datasets to evaluate demand, income, demographics, infrastructure, and development stage."}, {"id": "b9f059de-a55e-407b-b636-4ddfc32535fd", "type": "subtopic", "title": "CAGE distance and administrative barriers", "children": [{"id": "63684a20-df73-4da4-a4b1-4e0c9490146f", "type": "concept", "title": "Cultural distance and language"}, {"id": "de8c73fd-7617-47cd-95b6-2c1be6d37cde", "type": "concept", "title": "Regulation, institutions, and trade barriers"}, {"id": "4a25f11b-636a-4887-bd79-7da7bfce0bd5", "type": "concept", "title": "Logistics, infrastructure, and economic distance"}], "description": "Students learn why cultural, administrative, geographic, and economic distance changes market-entry cost and marketing design."}, {"id": "4fbeccb9-8223-43e8-a398-ccf99738f575", "type": "subtopic", "title": "Prioritization models", "children": [{"id": "b3ff20eb-d46e-4ca7-bc2b-bb71ed80cde8", "type": "concept", "title": "Weighted scoring models"}, {"id": "ef13abd9-fd10-46ce-b26a-0a8234ff23c2", "type": "concept", "title": "Risk-adjusted opportunity sizing"}, {"id": "f8532fca-df92-42e1-9724-83b579bfc1ec", "type": "concept", "title": "Sensitivity analysis and scenario logic"}], "description": "The point is to translate raw data into defensible market-selection decisions."}]}, {"id": "9636553a-e5b2-4b5a-9120-98c1d1bbbe1e", "type": "topic", "title": "Culture, Consumer Behavior, and Cross-Cultural Insight", "description": "Great global marketing depends on understanding culture without reducing people to simplistic national averages.", "children": [{"id": "e4049f3d-0b68-4243-9ad1-913ccd5aac5a", "type": "subtopic", "title": "Cultural frameworks", "children": [{"id": "a659e1b2-431a-4619-8ccd-44ec980464b7", "type": "concept", "title": "Power distance, individualism, uncertainty avoidance, and masculinity/femininity"}, {"id": "c6703957-3ed4-4542-a5e9-d62888949a71", "type": "concept", "title": "Universalism versus particularism and achievement versus ascription"}, {"id": "d313de03-bca8-4185-afd2-dc7d7e727f07", "type": "concept", "title": "Limits of national-culture indices"}], "description": "Students use Hofstede, Trompenaars, and related models as starting points for questions, not as final answers."}, {"id": "7427c1c7-7826-41f2-8406-00927684417d", "type": "subtopic", "title": "Consumer meaning and local practice", "children": [{"id": "5c9d56bb-bd62-4182-ae27-b6f2b2330680", "type": "concept", "title": "Consumer ethnography and observation"}, {"id": "b3a4047d-0b1a-4bb0-9374-c274420a6475", "type": "concept", "title": "Religion, family, class, gender, and age cohorts"}, {"id": "caad7ea0-955f-4185-8d61-37a2dac17851", "type": "concept", "title": "Language, humor, color, taboos, and symbolism"}], "description": "The gist is to study how products, brands, symbols, rituals, and media habits acquire local meaning."}, {"id": "09258e8a-c997-43d4-959c-2296cb9509ce", "type": "subtopic", "title": "Cultural intelligence for marketers", "children": [{"id": "daa656b9-e9d4-4676-9ea9-9891744a01da", "type": "concept", "title": "Bias awareness and stereotype avoidance"}, {"id": "c8b4f503-1433-4148-8b89-cb60884ebae6", "type": "concept", "title": "Localization research briefs"}, {"id": "58325408-c7ea-45bf-a853-595d77679e98", "type": "concept", "title": "Cross-cultural presentation and negotiation"}], "description": "Students learn how to work with local teams, agencies, and consumers respectfully and effectively."}]}, {"id": "cd5ff75b-bca9-4c6c-bb48-88a4e3a552eb", "type": "topic", "title": "Political, Legal, Trade, and Regulatory Environments", "description": "This section shows that marketing strategy is constrained and enabled by law, institutions, trade policy, privacy rules, and stakeholder power.", "children": [{"id": "af8359db-ce6f-4e2b-9b3a-c1235ef4c179", "type": "subtopic", "title": "Political and institutional risk", "children": [{"id": "f0705f42-411a-4ff9-9b6d-a866a055013e", "type": "concept", "title": "Country-risk indicators"}, {"id": "b9c87357-854e-4a7a-8499-886b681a33c2", "type": "concept", "title": "Stakeholder mapping"}, {"id": "38a29dbd-9a05-4d75-b64d-80d802fd390d", "type": "concept", "title": "Contingency planning"}], "description": "Students connect marketing decisions to government stability, corruption, rule of law, sanctions, conflict, and public trust."}, {"id": "403e7c29-f39f-4b66-bd2f-7081489ddab3", "type": "subtopic", "title": "Trade rules and market access", "children": [{"id": "869e1176-e506-417d-a372-fd88c6db03f1", "type": "concept", "title": "WTO principles"}, {"id": "f1edf4dc-cfb9-4c37-9c58-0a9307ccc941", "type": "concept", "title": "Regional economic integration"}, {"id": "540fa66a-5d31-4bc1-9dd0-85ed4528740f", "type": "concept", "title": "Rules of origin and customs processes"}], "description": "The point is to understand tariffs, quotas, standards, customs, and trade agreements as practical marketing constraints."}, {"id": "73aeceaa-6892-411f-bf8a-793553809bc7", "type": "subtopic", "title": "Marketing law and compliance", "children": [{"id": "fd3db391-9545-48dc-a789-fd882419777e", "type": "concept", "title": "GDPR and privacy-by-design"}, {"id": "9568eb5f-463c-49ae-8cc6-c0e28c75adcb", "type": "concept", "title": "Advertising claims and substantiation"}, {"id": "c86fb1e6-811e-4397-8a2a-4de2aff8faa0", "type": "concept", "title": "Trademark, counterfeiting, and brand protection"}], "description": "Students learn the basics of advertising regulation, data privacy, consumer protection, labeling, IP, and platform rules."}]}, {"id": "9bdc7875-33e1-4c71-af14-f0d5c8573649", "type": "topic", "title": "International Marketing Research and Customer Discovery", "description": "Students learn how to design research that works across language, culture, infrastructure, and data-access differences.", "children": [{"id": "58606b1f-d898-4a4e-9293-6ee82b0e6f96", "type": "subtopic", "title": "Research design across markets", "children": [{"id": "f1669981-4ef6-413a-8c13-b30f2e600600", "type": "concept", "title": "Exploratory, descriptive, and causal research"}, {"id": "7eacfdab-505d-42ea-9ea8-f4688a433482", "type": "concept", "title": "Qualitative interviews, ethnography, surveys, and experiments"}, {"id": "c2040de1-4c35-4fd8-a806-e365ad74c0b9", "type": "concept", "title": "Translation, back-translation, and measurement equivalence"}], "description": "The gist is to choose methods that fit the decision, market, budget, and cultural context."}, {"id": "f8454dd1-cfe0-441e-bb43-24c2d3074b0b", "type": "subtopic", "title": "Secondary and digital intelligence", "children": [{"id": "55023bdc-2a38-480f-8c30-8af3c41ce24f", "type": "concept", "title": "Government and multilateral datasets"}, {"id": "29129663-8308-4133-883c-a723310d4498", "type": "concept", "title": "Search, social, marketplace, and app-store signals"}, {"id": "f20c3732-3ea7-479b-b865-6af6b902ce8e", "type": "concept", "title": "Competitive and channel intelligence"}], "description": "Students use existing data responsibly before commissioning expensive fieldwork."}, {"id": "2d84ea7c-edcb-45b7-898d-587d3112ae6f", "type": "subtopic", "title": "Insight synthesis", "children": [{"id": "a47f4bbc-d946-4b91-83f7-6ffe0e939862", "type": "concept", "title": "Research briefs and hypotheses"}, {"id": "5de54ee8-68d5-49a9-b796-25bd3c2bbe21", "type": "concept", "title": "Customer journey maps"}, {"id": "3b884153-2bae-4e53-83ff-3db6a4c0e5cf", "type": "concept", "title": "Insight-to-action translation"}], "description": "The point is to convert findings into decisions about segmentation, entry, product, price, channel, and communications."}]}, {"id": "10d0ede6-d759-4ba6-b6fc-69b07f258d8b", "type": "topic", "title": "Global Segmentation, Targeting, and Positioning", "description": "This topic teaches students to segment across borders by real customer needs and economics rather than by country alone.", "children": [{"id": "b2175f82-18ed-4b08-9f50-cb9d4ac7c8fc", "type": "subtopic", "title": "Cross-national segmentation", "children": [{"id": "b7378269-2b8c-4ec8-b9da-f563b66febba", "type": "concept", "title": "Universal segments and local segments"}, {"id": "34a6ff94-6328-4051-8b0c-e57a3ac316eb", "type": "concept", "title": "Premium, value, youth, diaspora, and business segments"}, {"id": "7545513d-1a78-4590-b881-382147f98d25", "type": "concept", "title": "B2B versus B2C segmentation"}], "description": "Students compare geographic, demographic, psychographic, behavioral, and needs-based segmentation."}, {"id": "ce78714c-35cb-468f-8fba-ebd72d27b93d", "type": "subtopic", "title": "Targeting and portfolio choices", "children": [{"id": "2ddf1fa9-1785-47c4-9b1d-6a5a6ade8d5b", "type": "concept", "title": "Beachhead markets and sequencing"}, {"id": "1919b646-9906-461a-874c-206c3deccdd5", "type": "concept", "title": "Segment profitability and access"}, {"id": "d1806f41-9f44-485d-952d-29a3014e22be", "type": "concept", "title": "Competitive positioning gaps"}], "description": "The point is to choose where to compete and where not to compete."}, {"id": "5b9b926b-2ef8-4e5e-80f8-4ca0ea849064", "type": "subtopic", "title": "Positioning across cultures", "children": [{"id": "fdf9b887-0eeb-47df-a268-c1987e15919d", "type": "concept", "title": "Global brand promise"}, {"id": "c44210f1-f405-4d8c-b08f-580ff6fd25d4", "type": "concept", "title": "Local reasons to believe"}, {"id": "aa618d3f-7b4d-4f26-b874-5009b08e6d49", "type": "concept", "title": "Positioning maps and perceptual distance"}], "description": "Students learn to hold a clear value proposition while adapting proof, tone, imagery, and claims."}]}, {"id": "d421a85e-6dfe-457a-b9d6-ac6cb3781878", "type": "topic", "title": "Market Entry and International Expansion Strategy", "description": "Entry mode shapes the entire marketing system: control, risk, investment, learning, channel power, and speed.", "children": [{"id": "08e3cfbc-0810-46dc-b517-0c2d88e84406", "type": "subtopic", "title": "Entry-mode options", "children": [{"id": "10a0e994-cf86-4a27-aa5c-51ca54bb2017", "type": "concept", "title": "Control versus risk"}, {"id": "00d0cf1c-ac21-4115-80de-519c6bfc6dd0", "type": "concept", "title": "Capital intensity and speed"}, {"id": "abbb4c10-867a-4703-887b-cf6ca0594dcc", "type": "concept", "title": "Partner dependence and knowledge transfer"}], "description": "Students learn the strategic tradeoffs among exporting, licensing, franchising, alliances, joint ventures, acquisitions, subsidiaries, and digital-first entry."}, {"id": "cafc8aee-64c2-4979-9758-d0c3f3637942", "type": "subtopic", "title": "Go-to-market sequencing", "children": [{"id": "8de3b998-40d5-4322-9963-14e35650aa05", "type": "concept", "title": "Test markets and pilots"}, {"id": "63499ab2-6794-4027-8113-c8fd8e76ea68", "type": "concept", "title": "City-by-city and platform-led expansion"}, {"id": "e1cd81c9-893e-4bdc-b84f-291897349327", "type": "concept", "title": "Scaling triggers and exit criteria"}], "description": "The gist is to stage expansion intelligently instead of treating launch as a one-time event."}, {"id": "701eb561-e825-4a2b-aafd-e36677b803cc", "type": "subtopic", "title": "Partner and ecosystem strategy", "children": [{"id": "53a1eb84-2bb0-419f-bc7b-5498a681c7f1", "type": "concept", "title": "Partner selection"}, {"id": "c06d7308-7258-4c45-8cf1-95f01ff2e680", "type": "concept", "title": "Incentives and governance"}, {"id": "c3ccbf68-895f-44fd-8964-db2e343ee7b3", "type": "concept", "title": "Conflict management and performance metrics"}], "description": "Students examine distributors, retailers, platforms, agencies, local influencers, government actors, and logistics providers."}]}, {"id": "ad821095-68cc-46cb-ae24-e43a274c00c9", "type": "topic", "title": "Standardization, Adaptation, and Localization", "description": "Students learn the central global marketing tension: what should remain globally consistent and what must be adapted locally.", "children": [{"id": "38fd68a2-4f27-46c5-ae46-f296d34f416e", "type": "subtopic", "title": "Standardization economics", "children": [{"id": "8ca5a7a5-2f53-4858-b036-682e02bffe9a", "type": "concept", "title": "Global platforms and playbooks"}, {"id": "ad814417-a13f-4f1f-90ad-87824d5d1d29", "type": "concept", "title": "Brand consistency and production savings"}, {"id": "65f8ceb8-36f6-41c6-8f2e-e0611dbbfc08", "type": "concept", "title": "Knowledge reuse across markets"}], "description": "The point is to understand when global consistency creates scale, learning, brand equity, and operational efficiency."}, {"id": "8a850da6-d67c-4651-8b31-71a02fb85e8b", "type": "subtopic", "title": "Adaptation drivers", "children": [{"id": "06e2416a-8cf7-41de-9948-f8f6978b408f", "type": "concept", "title": "Product use conditions"}, {"id": "bf248e79-3690-41d0-a83d-7192da93f8d7", "type": "concept", "title": "Regulatory and labeling requirements"}, {"id": "b6dac451-788f-4e41-9600-58000967aa52", "type": "concept", "title": "Cultural fit and communication norms"}], "description": "Students identify when local customer needs, culture, law, climate, infrastructure, language, media, or competition require change."}, {"id": "39c9eebe-86e8-4fdc-8743-9e18dd1d2ee4", "type": "subtopic", "title": "Localization operating model", "children": [{"id": "8c4e2af8-980d-41ba-aecc-20285aca6dab", "type": "concept", "title": "Global guardrails"}, {"id": "2b2356a5-1148-4f97-8a9f-0afa32a3caca", "type": "concept", "title": "Local creative authority"}, {"id": "1af271a2-7ce3-4175-b890-97690f2447ee", "type": "concept", "title": "Feedback loops and governance"}], "description": "The gist is to design decision rights between headquarters, regions, and local teams."}]}, {"id": "2195a3e6-5293-4751-ad35-da8e7925ec74", "type": "topic", "title": "Global Brand Strategy and Brand Architecture", "description": "This unit studies how brands build meaning, trust, and equity across markets while avoiding cultural misfires and portfolio confusion.", "children": [{"id": "5b728ba2-0b8f-473e-9f67-875e551fe54d", "type": "subtopic", "title": "Global brand equity", "children": [{"id": "7fc88445-56d5-450c-8149-a3a95c2c7d6f", "type": "concept", "title": "Brand tracking by market"}, {"id": "e3af1333-0dad-4e86-bcf6-a294e42888eb", "type": "concept", "title": "Country-of-origin effects"}, {"id": "0059b21e-3e6f-4188-8acd-f1736950313a", "type": "concept", "title": "Trust, authenticity, and legitimacy"}], "description": "Students learn how awareness, associations, perceived quality, loyalty, and salience travel across borders."}, {"id": "3ae9fea3-f8f2-4d49-84a1-63a86f8afa36", "type": "subtopic", "title": "Brand architecture and naming", "children": [{"id": "7b30dedd-3ec8-41dd-a15a-d39c816fe1a4", "type": "concept", "title": "Global versus local brand names"}, {"id": "fcb98ded-cc69-4b0e-b45c-8e9d5e179966", "type": "concept", "title": "Pronunciation, translation, and legal clearance"}, {"id": "f4348ad9-69ef-4351-815d-5dbff104c345", "type": "concept", "title": "Portfolio roles and migration"}], "description": "The point is to decide when to use master brands, endorsed brands, local brands, acquisitions, or private labels."}, {"id": "a072f4a9-ea85-442a-91db-45f8b6e6e8ac", "type": "subtopic", "title": "Reputation and crisis management", "children": [{"id": "fd8a9b37-2d1b-4353-a8bc-8686cfd84ceb", "type": "concept", "title": "Issue monitoring"}, {"id": "055e6a4b-f726-4b34-ae91-f6d1946eaddb", "type": "concept", "title": "Local stakeholder response"}, {"id": "57b2bada-f915-4312-ba7a-101644d66081", "type": "concept", "title": "Apology, repair, and policy change"}], "description": "Students examine how global brands respond to activism, product failures, geopolitical controversy, and social-media backlash."}]}, {"id": "150ebd50-3f48-4a21-b5bd-348063d22d01", "type": "topic", "title": "Global Product, Service, and Innovation Strategy", "description": "Products and services must be designed for local jobs-to-be-done, infrastructure, regulation, economics, and cultural meaning.", "children": [{"id": "0652c081-8607-49c5-b4f3-da3e8e1e08c5", "type": "subtopic", "title": "Product adaptation and innovation", "children": [{"id": "2e24a435-2424-44b8-80ba-1aabc6bc55c4", "type": "concept", "title": "Core benefit versus local execution"}, {"id": "97bc0ae2-8cea-48bc-9299-2a6ff6c8e470", "type": "concept", "title": "Frugal innovation and reverse innovation"}, {"id": "d6a6c427-f1bd-4f39-ac0b-ae45f627c744", "type": "concept", "title": "Packaging, labeling, and language"}], "description": "Students learn how to modify features, packaging, size, quality level, design, and service models for different markets."}, {"id": "5de91bb0-713f-4324-8784-144caf3f9aa7", "type": "subtopic", "title": "Service localization", "children": [{"id": "20faab0d-216c-45ee-ad35-2ce612d1c7a0", "type": "concept", "title": "Customer support norms"}, {"id": "bd07ca45-f60e-427a-837d-5741e756f863", "type": "concept", "title": "Payment and fulfillment expectations"}, {"id": "09941008-c80d-4ba6-befb-7f7ffee20ca3", "type": "concept", "title": "Service quality across channels"}], "description": "The gist is to adapt customer experience, delivery, support, warranties, and service recovery."}, {"id": "3ccfc40a-165d-4156-9a27-98f1070d2784", "type": "subtopic", "title": "Portfolio and lifecycle management", "children": [{"id": "6bb27ede-3bfb-4ba7-b976-a49f1ffbd8b1", "type": "concept", "title": "Global product platforms"}, {"id": "89bcdab9-cd8d-4277-aa65-f4492db1b016", "type": "concept", "title": "Local SKU rationalization"}, {"id": "8cd4bb39-de83-4b10-a1b4-729c2f7bab4c", "type": "concept", "title": "Lifecycle stage by market"}], "description": "Students connect product decisions to launch sequencing, SKU complexity, cannibalization, and end-of-life decisions."}]}, {"id": "f244b4c5-4f6f-4314-92f9-347d1eba1ba2", "type": "topic", "title": "International Pricing, Currency, and Value Strategy", "description": "Pricing across borders requires economics, psychology, channel discipline, exchange-rate awareness, and fairness judgment.", "children": [{"id": "114f1c45-1eb0-4728-87ac-6bfe0c8d68de", "type": "subtopic", "title": "Price setting across markets", "children": [{"id": "da4edaf0-8446-47f9-af50-7701b44f7877", "type": "concept", "title": "Cost-plus, value-based, and competitive pricing"}, {"id": "2fd4b085-83dc-43b9-9d18-c5f48c3f8cbf", "type": "concept", "title": "Purchasing power parity and affordability"}, {"id": "fe1fe1b3-1a1a-485d-9ea1-fef70928ad6b", "type": "concept", "title": "Premium, value, and good-better-best ladders"}], "description": "Students learn how purchasing power, competition, costs, taxes, tariffs, and willingness to pay shape price architecture."}, {"id": "d560f638-31f2-40b6-b91d-18e173e29dfc", "type": "subtopic", "title": "FX, inflation, and financial exposure", "children": [{"id": "9d7ba7d5-8428-473f-aa22-fc69b197423b", "type": "concept", "title": "Currency pass-through"}, {"id": "df286f85-2237-4c0c-8bca-e7a2a5a5063c", "type": "concept", "title": "Hedging awareness for marketers"}, {"id": "6abddb11-5cf8-4877-a189-df4f5af3df41", "type": "concept", "title": "Indexing and repricing cadence"}], "description": "The point is to understand how exchange rates and inflation affect margins, price stability, and customer perception."}, {"id": "40d30561-2446-450a-a6a3-c2055f2967e3", "type": "subtopic", "title": "Parallel trade and gray markets", "children": [{"id": "005235a2-4d0a-4ca3-aeea-09bba5c78214", "type": "concept", "title": "Reference pricing"}, {"id": "59c5896c-e78d-42d6-81a7-2f10392333c8", "type": "concept", "title": "Distributor incentives"}, {"id": "26c9fdc4-0cc0-42bf-af76-a0da5a655d53", "type": "concept", "title": "Anti-diversion controls"}], "description": "Students examine how price differences create arbitrage, channel conflict, and brand-control problems."}]}, {"id": "57f6bc65-32e6-4ec0-813b-7df0e419c0f1", "type": "topic", "title": "Global Channels, Retail, Platforms, and Supply Interfaces", "description": "Marketing strategy lives or dies in channels: distributors, retailers, marketplaces, logistics, payments, and last-mile execution.", "children": [{"id": "1a8afbf4-5754-4ae5-9fa9-467d26f7857f", "type": "subtopic", "title": "Channel design", "children": [{"id": "b7f373d5-1e94-40cb-aa0d-c9d4407afca2", "type": "concept", "title": "Coverage, control, and cost"}, {"id": "5cf961e7-bb94-4f7d-adb5-cc687967e67c", "type": "concept", "title": "Modern trade versus traditional trade"}, {"id": "71f07829-fd09-4348-b8a9-2d738c2ca44a", "type": "concept", "title": "B2B channel structure"}], "description": "Students compare direct, distributor, agent, retail, franchise, marketplace, and omnichannel models."}, {"id": "11180358-cc41-4418-bd30-b27664c5907b", "type": "subtopic", "title": "Digital commerce and platforms", "children": [{"id": "ecfcf449-639d-4e71-9d82-2d959f75505b", "type": "concept", "title": "Amazon, Alibaba, Mercado Libre, Shopee, and local platforms"}, {"id": "c1ccaa14-8027-4790-a614-3e7372e1fe00", "type": "concept", "title": "Payments, trust, reviews, and fulfillment"}, {"id": "bffbc45a-3380-406d-8e66-8dc572ea0ba9", "type": "concept", "title": "Platform dependence and data access"}], "description": "The gist is to account for marketplaces, super apps, social commerce, and platform algorithms in global go-to-market plans."}, {"id": "d841019d-f556-441f-b63d-9bec84bb09ff", "type": "subtopic", "title": "Supply and service interfaces", "children": [{"id": "9d52a361-168e-4cbf-afbd-0328c8273c90", "type": "concept", "title": "Demand forecasting by market"}, {"id": "fa982289-7f5b-438c-b3fb-bb1f6ccbaa8d", "type": "concept", "title": "Last-mile logistics"}, {"id": "e6bb742f-1c45-4015-94ef-8a3ea253dedd", "type": "concept", "title": "Service-level agreements and channel metrics"}], "description": "Students learn how stockouts, lead times, cold chains, customs, returns, and service capacity affect customer promises."}]}, {"id": "7bf61ffb-c660-483e-a27a-097de98a505d", "type": "topic", "title": "Global Integrated Marketing Communications and Digital Growth", "description": "Communications must travel across language, media systems, platforms, culture, law, and measurement environments.", "children": [{"id": "2b46f13d-cfb1-46d2-839f-87cd7c8f4cac", "type": "subtopic", "title": "Global campaign strategy", "children": [{"id": "8ce2edad-df33-486a-aa6e-6e668b9de898", "type": "concept", "title": "Creative platform and local activation"}, {"id": "c5f9ae40-aea6-47c4-b7ed-9442bb45aa76", "type": "concept", "title": "Transcreation rather than literal translation"}, {"id": "bb1c6504-776a-483b-94f0-298ca796c720", "type": "concept", "title": "Media mix by market"}], "description": "Students learn how to create a global idea that can be locally expressed with relevance and compliance."}, {"id": "9e86afba-8b89-48e6-8bc1-bfd4ee5436ed", "type": "subtopic", "title": "Digital, search, social, and influencer marketing", "children": [{"id": "6af8104f-4450-4ab8-ac80-05f5d98c668a", "type": "concept", "title": "SEO/SEM localization"}, {"id": "b0332389-ef43-481c-8f22-9dd3d06fdef9", "type": "concept", "title": "Social platforms and creators"}, {"id": "ba2cd27d-98a5-4f54-a323-55599275cee3", "type": "concept", "title": "Messaging apps, communities, and social commerce"}], "description": "The point is to adapt digital growth tactics to local platforms, privacy rules, content norms, and consumer journeys."}, {"id": "f61a2fa4-9eb6-4123-906b-24139b0b32c4", "type": "subtopic", "title": "Measurement and marketing effectiveness", "children": [{"id": "2ad33211-7531-43e8-8422-6c88050ed638", "type": "concept", "title": "Brand lift, conversion, CAC, LTV, and incrementality"}, {"id": "4838d88d-90cc-473d-b907-09a0c32640b6", "type": "concept", "title": "MMM and experiment design basics"}, {"id": "8d86088a-cf4f-4110-9196-3b312fe3ef12", "type": "concept", "title": "Dashboard comparability across markets"}], "description": "Students learn to evaluate communications across markets while respecting attribution limits and data gaps."}]}, {"id": "24c7e7f1-6c12-4275-9627-76525e44d6b9", "type": "topic", "title": "Ethics, Sustainability, Inclusion, and Emerging Markets", "description": "World-class global marketing asks not only what works, but what is responsible, sustainable, inclusive, and legitimate.", "children": [{"id": "f294b1b7-5b36-4ffc-94cc-5bb808e5ca84", "type": "subtopic", "title": "Ethical global marketing", "children": [{"id": "f9fa7f13-d93c-4081-9e5d-d969a5f340cd", "type": "concept", "title": "Responsible targeting"}, {"id": "54a07006-0a54-4d1b-8ca3-f4ad0f870bc4", "type": "concept", "title": "Truthful claims and substantiation"}, {"id": "ac0fe6ee-df7d-4160-aa00-b53a773860c6", "type": "concept", "title": "Agency, labor, and supplier ethics"}], "description": "Students examine bribery, exploitation, consumer vulnerability, greenwashing, cultural appropriation, and misleading claims."}, {"id": "b69feb9e-f46b-4c22-9600-e37530960d5c", "type": "subtopic", "title": "Sustainability and circularity", "children": [{"id": "9573b3f5-9135-4c36-a7fe-1bff24daf33b", "type": "concept", "title": "Sustainable packaging and claims"}, {"id": "0408f77e-8117-4227-bb88-43f9fc09da99", "type": "concept", "title": "Lifecycle thinking"}, {"id": "07347663-b056-4b31-ac0f-69a45f5a52fb", "type": "concept", "title": "Local environmental regulation and expectations"}], "description": "The gist is to connect marketing claims to product design, packaging, logistics, climate impact, and credible reporting."}, {"id": "7583ee6e-1c87-42cf-aaba-3b5a33b5192c", "type": "subtopic", "title": "Inclusive and emerging-market strategy", "children": [{"id": "e641c18f-5766-4ac5-bc78-5af64b8e357c", "type": "concept", "title": "Base-of-pyramid and inclusive innovation"}, {"id": "40a1dd5b-35ca-49b2-8440-5de2c795d0ac", "type": "concept", "title": "Financial inclusion and digital access"}, {"id": "71cbb69d-083d-47b4-9a4c-4a3c101bcea1", "type": "concept", "title": "Local entrepreneurship and community partnerships"}], "description": "Students learn how to design for affordability, accessibility, trust, informal channels, and underserved consumers."}]}, {"id": "1a52232c-99dc-4102-ab60-d75d0e378499", "type": "topic", "title": "Global Marketing Analytics, Governance, and Capstone Planning", "description": "The course closes by integrating strategy, data, execution, and ethics into a defensible international marketing plan.", "children": [{"id": "a99c392c-99d4-4142-b71a-2b2d35e10bdb", "type": "subtopic", "title": "Global marketing dashboards", "children": [{"id": "0bcdd400-75d9-448d-85a9-6b460f0324a7", "type": "concept", "title": "Market attractiveness, funnel, brand, and financial metrics"}, {"id": "b9a9bc84-f836-4ebf-ba11-20a00c9ad29a", "type": "concept", "title": "Comparable definitions and data governance"}, {"id": "2e36faec-f001-4d7e-b0e8-5c8e08db7b7b", "type": "concept", "title": "Leading versus lagging indicators"}], "description": "Students learn what to measure globally, what to localize, and how to avoid false precision."}, {"id": "681eeb32-4e02-4eba-ab5d-05610eecb2a8", "type": "subtopic", "title": "Budgeting and resource allocation", "children": [{"id": "08d2c3f9-e262-4077-b1a5-4e93f58dc2bf", "type": "concept", "title": "Launch budgets and media allocation"}, {"id": "2a5e61f8-ef83-4ce8-9102-219c0595c661", "type": "concept", "title": "Scenario planning and hurdle rates"}, {"id": "4e49c8d4-3484-4c70-8cce-c35b07036bf4", "type": "concept", "title": "Portfolio resource tradeoffs"}], "description": "The point is to connect marketing plans to investment levels, risk, expected return, and learning milestones."}, {"id": "28830813-3616-4c5a-9d2b-0d5235286769", "type": "subtopic", "title": "Capstone market-entry recommendation", "children": [{"id": "f2a64885-7d4e-40de-af84-d5b5d2cf9b1f", "type": "concept", "title": "Market choice and rationale"}, {"id": "732493b0-e039-4e0c-b05f-c4583aa595c8", "type": "concept", "title": "STP, entry mode, 4Ps/7Ps, and metrics"}, {"id": "413e7638-fdd1-4d37-978f-767f63152e0a", "type": "concept", "title": "Risk register and implementation roadmap"}], "description": "Students synthesize research, strategy, tactics, financial logic, risk, and implementation into a board-ready plan."}]}], "dbBacked": true}$igmjson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'international-global-marketing'
);

update public.learning_paths
set
  title = 'International/Global Marketing',
  goal = 'International/Global Marketing',
  summary = 'This course prepares students to design, justify, and execute marketing strategy across borders. Students learn how culture, institutions, trade policy, market data, digital platforms, customer behavior, channel systems, pricing, brand architecture, regulation, sustainability, and geopolitical risk shape international marketing decisions. The course culminates in a market-entry or global expansion plan supported by data, customer insight, financial logic, and ethical judgment.',
  data = $igmjson${"slug": "international-global-marketing", "title": "International/Global Marketing", "description": "This course prepares students to design, justify, and execute marketing strategy across borders. Students learn how culture, institutions, trade policy, market data, digital platforms, customer behavior, channel systems, pricing, brand architecture, regulation, sustainability, and geopolitical risk shape international marketing decisions. The course culminates in a market-entry or global expansion plan supported by data, customer insight, financial logic, and ethical judgment.", "topics": [{"id": "4fffd20c-0835-42c7-8f2e-b9eaf8d92050", "type": "topic", "title": "Global Marketing Environment and Strategic Mindset", "description": "Students begin by learning how globalization, regionalization, technology, institutions, and consumer change reshape marketing decisions across borders.", "children": [{"id": "9ee59ef7-b6a5-4fa6-9f84-97c663fbd1a8", "type": "subtopic", "title": "Globalization, regionalization, and deglobalization", "children": [{"id": "45a5439b-6c12-4beb-9b8d-40270d0dd15b", "type": "concept", "title": "Global value chains and market interdependence"}, {"id": "5ca8dd80-cbe3-46ef-b580-2309fea822d3", "type": "concept", "title": "Regional blocs such as EU, USMCA, ASEAN, and AfCFTA"}, {"id": "1ad8f61d-39f4-4230-99de-895e55dfb6f8", "type": "concept", "title": "Resilience, reshoring, friend-shoring, and market fragmentation"}], "description": "The point is to see global marketing as a shifting strategic context, not simply selling the same product abroad."}, {"id": "600fe52f-0bd8-4747-8fd1-25e7ee0bbda7", "type": "subtopic", "title": "Global marketing strategy logic", "children": [{"id": "0ce8df60-e5c2-4490-8753-e9e3b9dd63d6", "type": "concept", "title": "Global integration versus local responsiveness"}, {"id": "1da5741e-a9a6-4b1d-af7d-6dce73072024", "type": "concept", "title": "Scale economies and local relevance"}, {"id": "d6258c03-4b54-4a6c-8ffc-ec9fda10f63c", "type": "concept", "title": "Global, regional, and local roles"}], "description": "Students learn how international marketing connects corporate strategy, competitive advantage, customer insight, and local execution."}, {"id": "a6b9fcd7-5ddc-4bfd-ba33-98db25e3b790", "type": "subtopic", "title": "Country and category opportunity framing", "children": [{"id": "d3bed472-c9e7-4c48-b103-a285a7ccb7ca", "type": "concept", "title": "Market size, growth, and profitability"}, {"id": "9567285b-90c6-4bca-b1a6-4972d78a4f8e", "type": "concept", "title": "Competitive intensity and white space"}, {"id": "0dff2753-5b32-4ebf-b84e-8646059b8c0b", "type": "concept", "title": "Capability fit and strategic priority"}], "description": "The gist is to distinguish country attractiveness from category readiness and company fit."}]}, {"id": "e5fabc1f-b69d-4015-9fee-b581224b1b90", "type": "topic", "title": "Country Screening, Market Attractiveness, and Data Sources", "description": "This topic builds the data discipline needed to choose markets using evidence rather than anecdotes or stereotypes.", "children": [{"id": "bf8f5d76-5632-4961-ac6a-8f2023186419", "type": "subtopic", "title": "Macro and market indicators", "children": [{"id": "5b924152-4ca4-47ea-8b66-46e87ecb65f4", "type": "concept", "title": "World Bank, OECD, IMF, WTO, and trade data"}, {"id": "e70a13ac-eb7f-4c32-a5a9-2eacda3706fb", "type": "concept", "title": "Population, income, urbanization, and category penetration"}, {"id": "9a2ce231-1519-4653-979f-5d28f8e0902b", "type": "concept", "title": "Data quality, comparability, and missingness"}], "description": "Students use public datasets to evaluate demand, income, demographics, infrastructure, and development stage."}, {"id": "b9f059de-a55e-407b-b636-4ddfc32535fd", "type": "subtopic", "title": "CAGE distance and administrative barriers", "children": [{"id": "63684a20-df73-4da4-a4b1-4e0c9490146f", "type": "concept", "title": "Cultural distance and language"}, {"id": "de8c73fd-7617-47cd-95b6-2c1be6d37cde", "type": "concept", "title": "Regulation, institutions, and trade barriers"}, {"id": "4a25f11b-636a-4887-bd79-7da7bfce0bd5", "type": "concept", "title": "Logistics, infrastructure, and economic distance"}], "description": "Students learn why cultural, administrative, geographic, and economic distance changes market-entry cost and marketing design."}, {"id": "4fbeccb9-8223-43e8-a398-ccf99738f575", "type": "subtopic", "title": "Prioritization models", "children": [{"id": "b3ff20eb-d46e-4ca7-bc2b-bb71ed80cde8", "type": "concept", "title": "Weighted scoring models"}, {"id": "ef13abd9-fd10-46ce-b26a-0a8234ff23c2", "type": "concept", "title": "Risk-adjusted opportunity sizing"}, {"id": "f8532fca-df92-42e1-9724-83b579bfc1ec", "type": "concept", "title": "Sensitivity analysis and scenario logic"}], "description": "The point is to translate raw data into defensible market-selection decisions."}]}, {"id": "9636553a-e5b2-4b5a-9120-98c1d1bbbe1e", "type": "topic", "title": "Culture, Consumer Behavior, and Cross-Cultural Insight", "description": "Great global marketing depends on understanding culture without reducing people to simplistic national averages.", "children": [{"id": "e4049f3d-0b68-4243-9ad1-913ccd5aac5a", "type": "subtopic", "title": "Cultural frameworks", "children": [{"id": "a659e1b2-431a-4619-8ccd-44ec980464b7", "type": "concept", "title": "Power distance, individualism, uncertainty avoidance, and masculinity/femininity"}, {"id": "c6703957-3ed4-4542-a5e9-d62888949a71", "type": "concept", "title": "Universalism versus particularism and achievement versus ascription"}, {"id": "d313de03-bca8-4185-afd2-dc7d7e727f07", "type": "concept", "title": "Limits of national-culture indices"}], "description": "Students use Hofstede, Trompenaars, and related models as starting points for questions, not as final answers."}, {"id": "7427c1c7-7826-41f2-8406-00927684417d", "type": "subtopic", "title": "Consumer meaning and local practice", "children": [{"id": "5c9d56bb-bd62-4182-ae27-b6f2b2330680", "type": "concept", "title": "Consumer ethnography and observation"}, {"id": "b3a4047d-0b1a-4bb0-9374-c274420a6475", "type": "concept", "title": "Religion, family, class, gender, and age cohorts"}, {"id": "caad7ea0-955f-4185-8d61-37a2dac17851", "type": "concept", "title": "Language, humor, color, taboos, and symbolism"}], "description": "The gist is to study how products, brands, symbols, rituals, and media habits acquire local meaning."}, {"id": "09258e8a-c997-43d4-959c-2296cb9509ce", "type": "subtopic", "title": "Cultural intelligence for marketers", "children": [{"id": "daa656b9-e9d4-4676-9ea9-9891744a01da", "type": "concept", "title": "Bias awareness and stereotype avoidance"}, {"id": "c8b4f503-1433-4148-8b89-cb60884ebae6", "type": "concept", "title": "Localization research briefs"}, {"id": "58325408-c7ea-45bf-a853-595d77679e98", "type": "concept", "title": "Cross-cultural presentation and negotiation"}], "description": "Students learn how to work with local teams, agencies, and consumers respectfully and effectively."}]}, {"id": "cd5ff75b-bca9-4c6c-bb48-88a4e3a552eb", "type": "topic", "title": "Political, Legal, Trade, and Regulatory Environments", "description": "This section shows that marketing strategy is constrained and enabled by law, institutions, trade policy, privacy rules, and stakeholder power.", "children": [{"id": "af8359db-ce6f-4e2b-9b3a-c1235ef4c179", "type": "subtopic", "title": "Political and institutional risk", "children": [{"id": "f0705f42-411a-4ff9-9b6d-a866a055013e", "type": "concept", "title": "Country-risk indicators"}, {"id": "b9c87357-854e-4a7a-8499-886b681a33c2", "type": "concept", "title": "Stakeholder mapping"}, {"id": "38a29dbd-9a05-4d75-b64d-80d802fd390d", "type": "concept", "title": "Contingency planning"}], "description": "Students connect marketing decisions to government stability, corruption, rule of law, sanctions, conflict, and public trust."}, {"id": "403e7c29-f39f-4b66-bd2f-7081489ddab3", "type": "subtopic", "title": "Trade rules and market access", "children": [{"id": "869e1176-e506-417d-a372-fd88c6db03f1", "type": "concept", "title": "WTO principles"}, {"id": "f1edf4dc-cfb9-4c37-9c58-0a9307ccc941", "type": "concept", "title": "Regional economic integration"}, {"id": "540fa66a-5d31-4bc1-9dd0-85ed4528740f", "type": "concept", "title": "Rules of origin and customs processes"}], "description": "The point is to understand tariffs, quotas, standards, customs, and trade agreements as practical marketing constraints."}, {"id": "73aeceaa-6892-411f-bf8a-793553809bc7", "type": "subtopic", "title": "Marketing law and compliance", "children": [{"id": "fd3db391-9545-48dc-a789-fd882419777e", "type": "concept", "title": "GDPR and privacy-by-design"}, {"id": "9568eb5f-463c-49ae-8cc6-c0e28c75adcb", "type": "concept", "title": "Advertising claims and substantiation"}, {"id": "c86fb1e6-811e-4397-8a2a-4de2aff8faa0", "type": "concept", "title": "Trademark, counterfeiting, and brand protection"}], "description": "Students learn the basics of advertising regulation, data privacy, consumer protection, labeling, IP, and platform rules."}]}, {"id": "9bdc7875-33e1-4c71-af14-f0d5c8573649", "type": "topic", "title": "International Marketing Research and Customer Discovery", "description": "Students learn how to design research that works across language, culture, infrastructure, and data-access differences.", "children": [{"id": "58606b1f-d898-4a4e-9293-6ee82b0e6f96", "type": "subtopic", "title": "Research design across markets", "children": [{"id": "f1669981-4ef6-413a-8c13-b30f2e600600", "type": "concept", "title": "Exploratory, descriptive, and causal research"}, {"id": "7eacfdab-505d-42ea-9ea8-f4688a433482", "type": "concept", "title": "Qualitative interviews, ethnography, surveys, and experiments"}, {"id": "c2040de1-4c35-4fd8-a806-e365ad74c0b9", "type": "concept", "title": "Translation, back-translation, and measurement equivalence"}], "description": "The gist is to choose methods that fit the decision, market, budget, and cultural context."}, {"id": "f8454dd1-cfe0-441e-bb43-24c2d3074b0b", "type": "subtopic", "title": "Secondary and digital intelligence", "children": [{"id": "55023bdc-2a38-480f-8c30-8af3c41ce24f", "type": "concept", "title": "Government and multilateral datasets"}, {"id": "29129663-8308-4133-883c-a723310d4498", "type": "concept", "title": "Search, social, marketplace, and app-store signals"}, {"id": "f20c3732-3ea7-479b-b865-6af6b902ce8e", "type": "concept", "title": "Competitive and channel intelligence"}], "description": "Students use existing data responsibly before commissioning expensive fieldwork."}, {"id": "2d84ea7c-edcb-45b7-898d-587d3112ae6f", "type": "subtopic", "title": "Insight synthesis", "children": [{"id": "a47f4bbc-d946-4b91-83f7-6ffe0e939862", "type": "concept", "title": "Research briefs and hypotheses"}, {"id": "5de54ee8-68d5-49a9-b796-25bd3c2bbe21", "type": "concept", "title": "Customer journey maps"}, {"id": "3b884153-2bae-4e53-83ff-3db6a4c0e5cf", "type": "concept", "title": "Insight-to-action translation"}], "description": "The point is to convert findings into decisions about segmentation, entry, product, price, channel, and communications."}]}, {"id": "10d0ede6-d759-4ba6-b6fc-69b07f258d8b", "type": "topic", "title": "Global Segmentation, Targeting, and Positioning", "description": "This topic teaches students to segment across borders by real customer needs and economics rather than by country alone.", "children": [{"id": "b2175f82-18ed-4b08-9f50-cb9d4ac7c8fc", "type": "subtopic", "title": "Cross-national segmentation", "children": [{"id": "b7378269-2b8c-4ec8-b9da-f563b66febba", "type": "concept", "title": "Universal segments and local segments"}, {"id": "34a6ff94-6328-4051-8b0c-e57a3ac316eb", "type": "concept", "title": "Premium, value, youth, diaspora, and business segments"}, {"id": "7545513d-1a78-4590-b881-382147f98d25", "type": "concept", "title": "B2B versus B2C segmentation"}], "description": "Students compare geographic, demographic, psychographic, behavioral, and needs-based segmentation."}, {"id": "ce78714c-35cb-468f-8fba-ebd72d27b93d", "type": "subtopic", "title": "Targeting and portfolio choices", "children": [{"id": "2ddf1fa9-1785-47c4-9b1d-6a5a6ade8d5b", "type": "concept", "title": "Beachhead markets and sequencing"}, {"id": "1919b646-9906-461a-874c-206c3deccdd5", "type": "concept", "title": "Segment profitability and access"}, {"id": "d1806f41-9f44-485d-952d-29a3014e22be", "type": "concept", "title": "Competitive positioning gaps"}], "description": "The point is to choose where to compete and where not to compete."}, {"id": "5b9b926b-2ef8-4e5e-80f8-4ca0ea849064", "type": "subtopic", "title": "Positioning across cultures", "children": [{"id": "fdf9b887-0eeb-47df-a268-c1987e15919d", "type": "concept", "title": "Global brand promise"}, {"id": "c44210f1-f405-4d8c-b08f-580ff6fd25d4", "type": "concept", "title": "Local reasons to believe"}, {"id": "aa618d3f-7b4d-4f26-b874-5009b08e6d49", "type": "concept", "title": "Positioning maps and perceptual distance"}], "description": "Students learn to hold a clear value proposition while adapting proof, tone, imagery, and claims."}]}, {"id": "d421a85e-6dfe-457a-b9d6-ac6cb3781878", "type": "topic", "title": "Market Entry and International Expansion Strategy", "description": "Entry mode shapes the entire marketing system: control, risk, investment, learning, channel power, and speed.", "children": [{"id": "08e3cfbc-0810-46dc-b517-0c2d88e84406", "type": "subtopic", "title": "Entry-mode options", "children": [{"id": "10a0e994-cf86-4a27-aa5c-51ca54bb2017", "type": "concept", "title": "Control versus risk"}, {"id": "00d0cf1c-ac21-4115-80de-519c6bfc6dd0", "type": "concept", "title": "Capital intensity and speed"}, {"id": "abbb4c10-867a-4703-887b-cf6ca0594dcc", "type": "concept", "title": "Partner dependence and knowledge transfer"}], "description": "Students learn the strategic tradeoffs among exporting, licensing, franchising, alliances, joint ventures, acquisitions, subsidiaries, and digital-first entry."}, {"id": "cafc8aee-64c2-4979-9758-d0c3f3637942", "type": "subtopic", "title": "Go-to-market sequencing", "children": [{"id": "8de3b998-40d5-4322-9963-14e35650aa05", "type": "concept", "title": "Test markets and pilots"}, {"id": "63499ab2-6794-4027-8113-c8fd8e76ea68", "type": "concept", "title": "City-by-city and platform-led expansion"}, {"id": "e1cd81c9-893e-4bdc-b84f-291897349327", "type": "concept", "title": "Scaling triggers and exit criteria"}], "description": "The gist is to stage expansion intelligently instead of treating launch as a one-time event."}, {"id": "701eb561-e825-4a2b-aafd-e36677b803cc", "type": "subtopic", "title": "Partner and ecosystem strategy", "children": [{"id": "53a1eb84-2bb0-419f-bc7b-5498a681c7f1", "type": "concept", "title": "Partner selection"}, {"id": "c06d7308-7258-4c45-8cf1-95f01ff2e680", "type": "concept", "title": "Incentives and governance"}, {"id": "c3ccbf68-895f-44fd-8964-db2e343ee7b3", "type": "concept", "title": "Conflict management and performance metrics"}], "description": "Students examine distributors, retailers, platforms, agencies, local influencers, government actors, and logistics providers."}]}, {"id": "ad821095-68cc-46cb-ae24-e43a274c00c9", "type": "topic", "title": "Standardization, Adaptation, and Localization", "description": "Students learn the central global marketing tension: what should remain globally consistent and what must be adapted locally.", "children": [{"id": "38fd68a2-4f27-46c5-ae46-f296d34f416e", "type": "subtopic", "title": "Standardization economics", "children": [{"id": "8ca5a7a5-2f53-4858-b036-682e02bffe9a", "type": "concept", "title": "Global platforms and playbooks"}, {"id": "ad814417-a13f-4f1f-90ad-87824d5d1d29", "type": "concept", "title": "Brand consistency and production savings"}, {"id": "65f8ceb8-36f6-41c6-8f2e-e0611dbbfc08", "type": "concept", "title": "Knowledge reuse across markets"}], "description": "The point is to understand when global consistency creates scale, learning, brand equity, and operational efficiency."}, {"id": "8a850da6-d67c-4651-8b31-71a02fb85e8b", "type": "subtopic", "title": "Adaptation drivers", "children": [{"id": "06e2416a-8cf7-41de-9948-f8f6978b408f", "type": "concept", "title": "Product use conditions"}, {"id": "bf248e79-3690-41d0-a83d-7192da93f8d7", "type": "concept", "title": "Regulatory and labeling requirements"}, {"id": "b6dac451-788f-4e41-9600-58000967aa52", "type": "concept", "title": "Cultural fit and communication norms"}], "description": "Students identify when local customer needs, culture, law, climate, infrastructure, language, media, or competition require change."}, {"id": "39c9eebe-86e8-4fdc-8743-9e18dd1d2ee4", "type": "subtopic", "title": "Localization operating model", "children": [{"id": "8c4e2af8-980d-41ba-aecc-20285aca6dab", "type": "concept", "title": "Global guardrails"}, {"id": "2b2356a5-1148-4f97-8a9f-0afa32a3caca", "type": "concept", "title": "Local creative authority"}, {"id": "1af271a2-7ce3-4175-b890-97690f2447ee", "type": "concept", "title": "Feedback loops and governance"}], "description": "The gist is to design decision rights between headquarters, regions, and local teams."}]}, {"id": "2195a3e6-5293-4751-ad35-da8e7925ec74", "type": "topic", "title": "Global Brand Strategy and Brand Architecture", "description": "This unit studies how brands build meaning, trust, and equity across markets while avoiding cultural misfires and portfolio confusion.", "children": [{"id": "5b728ba2-0b8f-473e-9f67-875e551fe54d", "type": "subtopic", "title": "Global brand equity", "children": [{"id": "7fc88445-56d5-450c-8149-a3a95c2c7d6f", "type": "concept", "title": "Brand tracking by market"}, {"id": "e3af1333-0dad-4e86-bcf6-a294e42888eb", "type": "concept", "title": "Country-of-origin effects"}, {"id": "0059b21e-3e6f-4188-8acd-f1736950313a", "type": "concept", "title": "Trust, authenticity, and legitimacy"}], "description": "Students learn how awareness, associations, perceived quality, loyalty, and salience travel across borders."}, {"id": "3ae9fea3-f8f2-4d49-84a1-63a86f8afa36", "type": "subtopic", "title": "Brand architecture and naming", "children": [{"id": "7b30dedd-3ec8-41dd-a15a-d39c816fe1a4", "type": "concept", "title": "Global versus local brand names"}, {"id": "fcb98ded-cc69-4b0e-b45c-8e9d5e179966", "type": "concept", "title": "Pronunciation, translation, and legal clearance"}, {"id": "f4348ad9-69ef-4351-815d-5dbff104c345", "type": "concept", "title": "Portfolio roles and migration"}], "description": "The point is to decide when to use master brands, endorsed brands, local brands, acquisitions, or private labels."}, {"id": "a072f4a9-ea85-442a-91db-45f8b6e6e8ac", "type": "subtopic", "title": "Reputation and crisis management", "children": [{"id": "fd8a9b37-2d1b-4353-a8bc-8686cfd84ceb", "type": "concept", "title": "Issue monitoring"}, {"id": "055e6a4b-f726-4b34-ae91-f6d1946eaddb", "type": "concept", "title": "Local stakeholder response"}, {"id": "57b2bada-f915-4312-ba7a-101644d66081", "type": "concept", "title": "Apology, repair, and policy change"}], "description": "Students examine how global brands respond to activism, product failures, geopolitical controversy, and social-media backlash."}]}, {"id": "150ebd50-3f48-4a21-b5bd-348063d22d01", "type": "topic", "title": "Global Product, Service, and Innovation Strategy", "description": "Products and services must be designed for local jobs-to-be-done, infrastructure, regulation, economics, and cultural meaning.", "children": [{"id": "0652c081-8607-49c5-b4f3-da3e8e1e08c5", "type": "subtopic", "title": "Product adaptation and innovation", "children": [{"id": "2e24a435-2424-44b8-80ba-1aabc6bc55c4", "type": "concept", "title": "Core benefit versus local execution"}, {"id": "97bc0ae2-8cea-48bc-9299-2a6ff6c8e470", "type": "concept", "title": "Frugal innovation and reverse innovation"}, {"id": "d6a6c427-f1bd-4f39-ac0b-ae45f627c744", "type": "concept", "title": "Packaging, labeling, and language"}], "description": "Students learn how to modify features, packaging, size, quality level, design, and service models for different markets."}, {"id": "5de91bb0-713f-4324-8784-144caf3f9aa7", "type": "subtopic", "title": "Service localization", "children": [{"id": "20faab0d-216c-45ee-ad35-2ce612d1c7a0", "type": "concept", "title": "Customer support norms"}, {"id": "bd07ca45-f60e-427a-837d-5741e756f863", "type": "concept", "title": "Payment and fulfillment expectations"}, {"id": "09941008-c80d-4ba6-befb-7f7ffee20ca3", "type": "concept", "title": "Service quality across channels"}], "description": "The gist is to adapt customer experience, delivery, support, warranties, and service recovery."}, {"id": "3ccfc40a-165d-4156-9a27-98f1070d2784", "type": "subtopic", "title": "Portfolio and lifecycle management", "children": [{"id": "6bb27ede-3bfb-4ba7-b976-a49f1ffbd8b1", "type": "concept", "title": "Global product platforms"}, {"id": "89bcdab9-cd8d-4277-aa65-f4492db1b016", "type": "concept", "title": "Local SKU rationalization"}, {"id": "8cd4bb39-de83-4b10-a1b4-729c2f7bab4c", "type": "concept", "title": "Lifecycle stage by market"}], "description": "Students connect product decisions to launch sequencing, SKU complexity, cannibalization, and end-of-life decisions."}]}, {"id": "f244b4c5-4f6f-4314-92f9-347d1eba1ba2", "type": "topic", "title": "International Pricing, Currency, and Value Strategy", "description": "Pricing across borders requires economics, psychology, channel discipline, exchange-rate awareness, and fairness judgment.", "children": [{"id": "114f1c45-1eb0-4728-87ac-6bfe0c8d68de", "type": "subtopic", "title": "Price setting across markets", "children": [{"id": "da4edaf0-8446-47f9-af50-7701b44f7877", "type": "concept", "title": "Cost-plus, value-based, and competitive pricing"}, {"id": "2fd4b085-83dc-43b9-9d18-c5f48c3f8cbf", "type": "concept", "title": "Purchasing power parity and affordability"}, {"id": "fe1fe1b3-1a1a-485d-9ea1-fef70928ad6b", "type": "concept", "title": "Premium, value, and good-better-best ladders"}], "description": "Students learn how purchasing power, competition, costs, taxes, tariffs, and willingness to pay shape price architecture."}, {"id": "d560f638-31f2-40b6-b91d-18e173e29dfc", "type": "subtopic", "title": "FX, inflation, and financial exposure", "children": [{"id": "9d7ba7d5-8428-473f-aa22-fc69b197423b", "type": "concept", "title": "Currency pass-through"}, {"id": "df286f85-2237-4c0c-8bca-e7a2a5a5063c", "type": "concept", "title": "Hedging awareness for marketers"}, {"id": "6abddb11-5cf8-4877-a189-df4f5af3df41", "type": "concept", "title": "Indexing and repricing cadence"}], "description": "The point is to understand how exchange rates and inflation affect margins, price stability, and customer perception."}, {"id": "40d30561-2446-450a-a6a3-c2055f2967e3", "type": "subtopic", "title": "Parallel trade and gray markets", "children": [{"id": "005235a2-4d0a-4ca3-aeea-09bba5c78214", "type": "concept", "title": "Reference pricing"}, {"id": "59c5896c-e78d-42d6-81a7-2f10392333c8", "type": "concept", "title": "Distributor incentives"}, {"id": "26c9fdc4-0cc0-42bf-af76-a0da5a655d53", "type": "concept", "title": "Anti-diversion controls"}], "description": "Students examine how price differences create arbitrage, channel conflict, and brand-control problems."}]}, {"id": "57f6bc65-32e6-4ec0-813b-7df0e419c0f1", "type": "topic", "title": "Global Channels, Retail, Platforms, and Supply Interfaces", "description": "Marketing strategy lives or dies in channels: distributors, retailers, marketplaces, logistics, payments, and last-mile execution.", "children": [{"id": "1a8afbf4-5754-4ae5-9fa9-467d26f7857f", "type": "subtopic", "title": "Channel design", "children": [{"id": "b7f373d5-1e94-40cb-aa0d-c9d4407afca2", "type": "concept", "title": "Coverage, control, and cost"}, {"id": "5cf961e7-bb94-4f7d-adb5-cc687967e67c", "type": "concept", "title": "Modern trade versus traditional trade"}, {"id": "71f07829-fd09-4348-b8a9-2d738c2ca44a", "type": "concept", "title": "B2B channel structure"}], "description": "Students compare direct, distributor, agent, retail, franchise, marketplace, and omnichannel models."}, {"id": "11180358-cc41-4418-bd30-b27664c5907b", "type": "subtopic", "title": "Digital commerce and platforms", "children": [{"id": "ecfcf449-639d-4e71-9d82-2d959f75505b", "type": "concept", "title": "Amazon, Alibaba, Mercado Libre, Shopee, and local platforms"}, {"id": "c1ccaa14-8027-4790-a614-3e7372e1fe00", "type": "concept", "title": "Payments, trust, reviews, and fulfillment"}, {"id": "bffbc45a-3380-406d-8e66-8dc572ea0ba9", "type": "concept", "title": "Platform dependence and data access"}], "description": "The gist is to account for marketplaces, super apps, social commerce, and platform algorithms in global go-to-market plans."}, {"id": "d841019d-f556-441f-b63d-9bec84bb09ff", "type": "subtopic", "title": "Supply and service interfaces", "children": [{"id": "9d52a361-168e-4cbf-afbd-0328c8273c90", "type": "concept", "title": "Demand forecasting by market"}, {"id": "fa982289-7f5b-438c-b3fb-bb1f6ccbaa8d", "type": "concept", "title": "Last-mile logistics"}, {"id": "e6bb742f-1c45-4015-94ef-8a3ea253dedd", "type": "concept", "title": "Service-level agreements and channel metrics"}], "description": "Students learn how stockouts, lead times, cold chains, customs, returns, and service capacity affect customer promises."}]}, {"id": "7bf61ffb-c660-483e-a27a-097de98a505d", "type": "topic", "title": "Global Integrated Marketing Communications and Digital Growth", "description": "Communications must travel across language, media systems, platforms, culture, law, and measurement environments.", "children": [{"id": "2b46f13d-cfb1-46d2-839f-87cd7c8f4cac", "type": "subtopic", "title": "Global campaign strategy", "children": [{"id": "8ce2edad-df33-486a-aa6e-6e668b9de898", "type": "concept", "title": "Creative 